#include <cassert>
#include <cmath>
#include <string>
#include <unordered_map>

enum class Driver { None, AI, Player2 };
struct Vec2 { float x, y; Vec2(float px=0.0f, float py=0.0f):x(px),y(py){} };
struct Coop {
    Vec2 kirby, helper;
    bool helperActive = false;
    Driver helperDriver = Driver::None;
    float cameraX = 0.0f;
    float maxDistance = 10.0f; // 예시 월드 유닛

    bool Summon(bool hasCopyAbility) {
        if (!hasCopyAbility || helperActive) return false;
        helperActive = true;
        helperDriver = Driver::AI;
        helper = {kirby.x + 1.0f, kirby.y};
        return true;
    }
    void JoinP2() {
        if (helperActive) helperDriver = Driver::Player2;
    }
    void LeaveP2() {
        if (helperActive) helperDriver = Driver::AI;
    }
    void Tick() {
        cameraX = kirby.x; // 카메라 우선권은 주인공
        if (!helperActive) return;
        if (std::fabs(helper.x - cameraX) > maxDistance) {
            const float side = helper.x > cameraX ? 1.0f : -1.0f;
            helper.x = cameraX + side * (maxDistance * 0.5f);
        }
    }
};

struct Progress {
    // 시나리오마다 고정 ID 사용. 표시 순서와 저장 키를 결합하지 않는다.
    std::unordered_map<std::string, bool> cleared;
    void Complete(const std::string& scenarioId) { cleared[scenarioId] = true; }
    bool IsClear(const std::string& id) const {
        auto it = cleared.find(id);
        return it != cleared.end() && it->second;
    }
};

int main() {
    Coop game;
    assert(!game.Summon(false));
    assert(game.Summon(true));
    assert(game.helperDriver == Driver::AI);
    game.JoinP2();
    assert(game.helperDriver == Driver::Player2);
    game.kirby.x = 20.0f;
    game.helper.x = -100.0f;
    game.Tick();
    assert(game.cameraX == 20.0f);
    assert(std::fabs(game.helper.x - game.cameraX) <= 10.0f);
    game.LeaveP2();
    assert(game.helperDriver == Driver::AI);
    Progress save;
    save.Complete("short-adventure");
    assert(save.IsClear("short-adventure"));
    assert(!save.IsClear("treasure-hunt"));
}
